import { createRuntime } from "@tsa/runtime-kernel";

const runtime = createRuntime();

const session = runtime.start();

const activity = session.currentActivity();


console.log(session.currentActivity());

session.next();

console.log(session.currentActivity());

let body = "";

switch (activity.content.type) {
  case "reading":
    body = activity.content.body;
    break;

  case "reflection":
    body = activity.content.prompt;
    break;
}

export default function Home() {
  return (
    <main className="min-h-screen bg-zinc-50">
      <div className="mx-auto max-w-4xl px-8 py-20">

        <p className="text-sm uppercase tracking-[0.25em] text-blue-600">
          Technical Stewardship Academy
        </p>

        <h1 className="mt-3 text-5xl font-bold tracking-tight">
          Engineering Foundations
        </h1>

        <p className="mt-3 text-xl text-zinc-600">
          Thinking Like an Engineer
        </p>

        <div className="mt-16 rounded-2xl border bg-white p-10 shadow-sm">

          <p className="text-xs uppercase tracking-[0.25em] text-zinc-500">
            {activity.title}
          </p>

          <p className="mt-8 text-3xl leading-relaxed">
            {body}
          </p>

          <div className="mt-10 flex items-center justify-between">

            <span className="text-sm text-zinc-500">
              {activity.estimatedMinutes} min
            </span>

            <button className="rounded-xl bg-black px-6 py-3 text-white hover:bg-zinc-800 transition">
              Start Learning
            </button>

          </div>

        </div>

      </div>
    </main>
  );
}